const portalCampaigns=[{label:'VPJ · CƠ HỘI NGHỀ NGHIỆP',title:'Việc làm nhà máy.<br>Cơ hội gần nhà.',cta:'Khám phá việc sản xuất',glyph:'↗',action:'production'},{label:'VPJ · HỒ SƠ & CV',title:'Hồ sơ ấn tượng.<br>Sẵn sàng ứng tuyển.',cta:'Tạo CV của bạn',glyph:'▤',action:'profile'},{label:'VPJ · NHÀ TUYỂN DỤNG',title:'Tìm đúng người.<br>Cùng phát triển.',cta:'Khám phá VPJ Business',glyph:'◎',action:'employer'}];let portalCampaignIndex=0;
function campaignAction(action){if(action==='production'){reset();$$('input[name=category]').forEach(e=>e.checked=e.value==='Sản xuất');view('jobs');render();$('#resultCount').scrollIntoView({behavior:'smooth',block:'center'})}else view(action)}
function renderPortalCampaigns(){$('#portalBanners').innerHTML=[0,1,2].map(i=>{const c=portalCampaigns[(portalCampaignIndex+i)%portalCampaigns.length];return `<article class="portal-banner"><span>${c.label}</span><h3>${c.title}</h3><button data-campaign="${c.action}">${c.cta} ↗</button><span class="banner-glyph" aria-hidden="true">${c.glyph}</span></article>`}).join('');$$('[data-campaign]').forEach(b=>b.onclick=()=>campaignAction(b.dataset.campaign))}
$('#bannerPrev').onclick=()=>{portalCampaignIndex=(portalCampaignIndex+2)%3;renderPortalCampaigns()};$('#bannerNext').onclick=()=>{portalCampaignIndex=(portalCampaignIndex+1)%3;renderPortalCampaigns()};renderPortalCampaigns();
const portalFeatured=jobs.filter(j=>!j.owned).slice(0,4);$('#featuredGrid').innerHTML=portalFeatured.map(j=>`<article class="spotlight-job"><div class="spotlight-head"><div class="company-logo" style="background:${j.color};color:${j.ink}">${esc(j.logo)}</div><span class="hot-pill">TIN MẪU</span></div><h3><button data-detail="${j.id}">${esc(j.title)}</button></h3><p>${esc(j.company)}</p><div class="salary">${j.min} – ${j.max} triệu / tháng</div><div class="spotlight-meta"><span>⌖ ${esc(j.location)}</span><span>${j.exp==='Không cần kinh nghiệm'?'Được đào tạo':'Có kinh nghiệm'}</span></div></article>`).join('');$('#allFeatured').onclick=()=>$('#resultCount').scrollIntoView({behavior:'smooth',block:'center'});
$('#locationStrip').innerHTML='<span>Việc làm theo khu vực:</span>'+['Vĩnh Yên','Phúc Yên','Bình Xuyên','Tam Dương','Yên Lạc'].map(t=>`<button data-region="${t}">${t}</button>`).join('');$$('[data-region]').forEach(b=>b.onclick=()=>{reset();$('#location').value=b.dataset.region;render();$('#resultCount').scrollIntoView({behavior:'smooth',block:'center'})});
$('#asideProfile').onclick=()=>view('profile');$('#asideAllSources').onclick=()=>view('sources');$('#asideGuides').onclick=()=>view('guides');$('#utilityEmployer').onclick=()=>view('employer');$('#asideSources').innerHTML=sourcesVPJ.slice(0,3).map(s=>`<a class="quick-source" href="${s.url}" target="_blank" rel="noopener noreferrer"><b>${s.symbol}</b><span>${s.name}</span><span>↗</span></a>`).join('');
$('#employerShowcase').innerHTML=companies.slice(0,6).map(j=>`<button class="employer-tile" data-employerpick="${esc(j.company)}"><div class="company-logo" style="background:${j.color};color:${j.ink}">${esc(j.logo)}</div><h3>${esc(j.company)}</h3><small>${esc(j.location)} · Doanh nghiệp mẫu</small></button>`).join('');$$('[data-employerpick]').forEach(b=>b.onclick=()=>{reset();$('#query').value=b.dataset.employerpick;view('jobs');$('#resultCount').scrollIntoView({behavior:'smooth',block:'center'})});
$('#editorialCards').innerHTML=guideContentVPJ.map((g,i)=>`<article class="editorial-card"><span class="editorial-number">0${i+1}</span><h3>${g.title}</h3><p>${g.desc}</p><button class="detail-button" data-editorial="${i}">Đọc bài viết ↗</button></article>`).join('');$$('[data-editorial]').forEach(b=>b.onclick=()=>{const g=guideContentVPJ[+b.dataset.editorial];openModal(`<h2>${g.title}</h2><p>${g.desc}</p><ul style="line-height:2;color:#617168;font-size:14px">${g.body.map(x=>`<li>${x}</li>`).join('')}</ul>`)});
const iconsPortal=['<rect x="4" y="7" width="16" height="14" rx="2"/><path d="M8 7V3h8v4M9 12h6M9 16h6"/>','<circle cx="12" cy="12" r="8"/><path d="m8 12 3 3 5-6"/>','<path d="m14 6 4-3 3 3-3 4-3-1-6 6 1 3-4 3-3-3 3-4 3 1 6-6-1-3Z"/>','<rect x="4" y="5" width="16" height="16" rx="2"/><path d="M8 5V3h8v2M8 10h8M8 14h8M8 18h5"/>','<rect x="5" y="3" width="14" height="18" rx="2"/><path d="M8 7h8M8 12h2M14 12h2M8 16h2M14 16h2"/>','<path d="M4 8h16l-1 12H5L4 8ZM8 8V6a4 4 0 0 1 8 0v2"/>'];$$('#categoryGrid .category-tile i').forEach((e,i)=>e.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${iconsPortal[i]}</svg>`);
$$('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));
